const MODAL = ".dg-node-search-modal";
const INPUT = `${MODAL} [role="textbox"]`;
const PREVIEW = `${MODAL} div.overflow-y-auto.px-4`;
const CLAIM_ID = "node_vifgmehqDtYmQFU--Uwxa";

const filler = (label, n) =>
  Array.from({ length: n }, (_, i) => `Filler ${label} paragraph ${i + 1} with enough words to take a line of height.`).join("\n\n");

const PROBE_BODY = `# Heading One
First paragraph line one
continues on line two quokkapara #evd-candidate
and line three.

Second paragraph after one blank.

- level1 A
  continuation of A
  - level2 B quokkanest #clm-candidate
    - level3 C
      continuation of C quokkacont #evd-candidate
  - level2 D
- level1 E
1. ordered one
2. ordered two
Paragraph right after list with no blank.

