$$

Footnote ref here[^1].

[^1]: footnote text

![[2026.01.14]]

![[Pasted image 20260722165704.png]]

Link [[2026.01.14|alias text]] and **bold** and _italic_ and \`code\` and ==highlight== and #tag here quokkafmt #clm-candidate
`;

const PROBE = `---
title: Locator probe
tags: [probe]
---
${filler("top", 60)}

${PROBE_BODY}
${filler("tail", 20)}
`;

const ZEPHYR = `Intro paragraph about zephyr winds

${filler("z1", 50)}

Zephyrpara winds cool the coast #clm-candidate

${filler("z2", 50)}

- Zephyrlist gauge readings rose 4% #evd-candidate

${filler("z3", 50)}

## Zephyrhead heading claim #clm-candidate

${filler("z4", 20)}
`;

const RESET = `---
nodeTypeId: ${CLAIM_ID}
---
${filler("r1", 60)}

Quokkareset tagged line #clm-candidate

${filler("r2", 20)}
`;

const FILES = { "locator-probe.md": PROBE, "zephyr-candidates.md": ZEPHYR, "Quokka reset node.md": RESET };

const openWithCandidates = async ({ client, json, vault }, query) => {
  await client.evaluate(`return app.commands.executeCommandById(${json(`${vault.pluginId}:open-node-search`)});`);
  await client.waitFor(`!!document.querySelector(${json(INPUT)})`, { label: "search input" });
  const trigger = `document.querySelector(${json(`${MODAL} button[aria-label="Display options"]`)})`;
  await client.evaluate(`${trigger}.click(); return true;`);
  await client.waitFor(`!!document.querySelector('[role=menuitemcheckbox]')`, { label: "options menu" });
  await client.evaluate(`document.querySelector('[role=menuitemcheckbox]').click(); return true;`);
  await client.waitFor(`document.querySelector('[role=menuitemcheckbox]')?.getAttribute('aria-checked') === 'true'`, { label: "toggle on" });
  await client.evaluate(`${trigger}.click(); return true;`);
  await client.evaluate(`document.querySelector(${json(INPUT)}).focus(); return true;`);
  await client.typeText(query);
};

// Row matcher runs in page: subtitle "#tag · basename · L<n>" or plain title for nodes.
const rowExpr = (json, { sub, title }) =>
  `Array.from(document.querySelectorAll(${json(`${MODAL} [role=option]`)})).findIndex((el) => ${
    sub
      ? `(el.querySelector('.text-xs')?.textContent ?? '').includes(${json(sub)})`
      : `!el.querySelector('.text-xs') && el.querySelector('.dg-search-result-title')?.textContent === ${json(title)}`
  })`;

const select = async ({ client, json }, row) => {
  await client.waitFor(`${rowExpr(json, row)} >= 0`, { label: `row ${JSON.stringify(row)}`, timeout: 8000 });
  await client.evaluate(`const i = ${rowExpr(json, row)}; document.querySelectorAll(${json(`${MODAL} [role=option]`)})[i].click(); return true;`);
};

const measure = ({ client, json }) =>
  client.evaluate(`
    const c = document.querySelector(${json(PREVIEW)});
    if (!c) return { error: "no preview" };
    const el = c.querySelector(".dg-search-preview-flash");
    const own = (e) => { const k = e.cloneNode(true); k.querySelectorAll("ul, ol").forEach((n) => n.remove()); return k.textContent.replace(/\\s+/g, " ").trim(); };
    const cr = c.getBoundingClientRect();
    const r = el?.getBoundingClientRect();
    return {
      scrollTop: Math.round(c.scrollTop), scrollHeight: c.scrollHeight,
      tag: el?.tagName ?? null, text: el ? own(el).slice(0, 70) : null,
      inView: !!r && r.top >= cr.top && r.bottom <= cr.bottom,
      flashCount: c.querySelectorAll(".dg-search-preview-flash").length,
      header: document.querySelector(${json(`${MODAL} .font-semibold`)})?.textContent,
    };`);

const waitFlash = (ctx, needle) =>
  ctx.client.waitFor(
    `(() => { const el = document.querySelector(${ctx.json(`${PREVIEW} .dg-search-preview-flash`)}); return !!el && el.textContent.includes(${ctx.json(needle)}); })()`,
    { label: `flash on ${needle}`, timeout: 8000 },
  );

const settle = () => new Promise((r) => setTimeout(r, 300));

const fmt = (m) => `${m.tag} "${m.text}" scrollTop=${m.scrollTop} inView=${m.inView} flash=${m.flashCount}`;

const candidateScenario = ({ name, query, row, needle, check, expected }) => ({
  name,
  input: `toggle candidates; type "${query}"; select ${row.sub}`,
  expected,
  run: async (ctx) => {
    await openWithCandidates(ctx, query);
    await select(ctx, row);
    await waitFlash(ctx, needle);
    await settle();
    return measure(ctx);
  },
  expect: (m) => ({ pass: m.scrollTop > 0 && m.inView && m.flashCount === 1 && check(m), actual: fmt(m) }),
});

const lineOf = (body, needle) => body.split("\n").findIndex((l) => l.includes(needle)) + 1;

export default [
  {
    name: "Fixtures indexed",
    input: "write 3 fixtures; wait for metadataCache tags",
    expected: "every tagged fixture line is in the tag cache",
    run: async (ctx) => {
      const out = {};
      for (const [name, body] of Object.entries(FILES)) {
        const p = await ctx.writeNote(name, body);
        const want = body.split("\n").filter((l) => /#(clm|evd)-candidate/.test(l)).length;
        await ctx.client.waitFor(
          `(app.metadataCache.getFileCache(app.vault.getAbstractFileByPath(${ctx.json(p)}))?.tags ?? []).filter((t) => /candidate/.test(t.tag)).length === ${want}`,
          { label: `cache ${name}`, timeout: 15000 },
        );
        out[name] = want;
      }
      await settle();
      return out;
    },
    expect: (o) => ({ pass: o["locator-probe.md"] === 6 && o["zephyr-candidates.md"] === 3, actual: JSON.stringify(o) }),
  },
  candidateScenario({
    name: "a1 paragraph candidate",
    query: "zephyrpara", row: { sub: `zephyr-candidates · L${lineOf(ZEPHYR, "Zephyrpara")}` }, needle: "Zephyrpara",
    check: (m) => m.tag === "P", expected: "P scrolled into view, flashed",
  }),
  candidateScenario({
    name: "a2 list line candidate",
    query: "zephyrlist", row: { sub: `zephyr-candidates · L${lineOf(ZEPHYR, "Zephyrlist")}` }, needle: "Zephyrlist",
    check: (m) => m.tag === "LI", expected: "LI scrolled into view, flashed",
  }),
  {
    // Only result, auto-active at index 0: exercises the render-then-scroll path.
    name: "a3 heading candidate (auto-active)",
    input: 'toggle candidates; type "zephyrhead"; no click',
    expected: "H2 scrolled into view, flashed",
    run: async (ctx) => {
      await openWithCandidates(ctx, "zephyrhead");
      await waitFlash(ctx, "Zephyrhead");
      await settle();
      return measure(ctx);
    },
    expect: (m) => ({ pass: m.tag === "H2" && m.scrollTop > 0 && m.inView && m.flashCount === 1, actual: fmt(m) }),
  },
  candidateScenario({
    name: "b1 nested level2 item",
    query: "quokkanest", row: { sub: `locator-probe · L${lineOf(PROBE, "quokkanest") }` }, needle: "quokkanest",
    check: (m) => m.tag === "LI" && m.text.startsWith("level2 B"), expected: "innermost LI 'level2 B', not level1 A",
  }),
  candidateScenario({
    name: "b2 continuation line",
    query: "quokkacont", row: { sub: `locator-probe · L${lineOf(PROBE, "quokkacont")}` }, needle: "quokkacont",
    check: (m) => m.tag === "LI" && m.text.startsWith("level3 C"), expected: "innermost LI 'level3 C'",
  }),
  candidateScenario({
    name: "c table row",
    query: "quokkarow", row: { sub: `locator-probe · L${lineOf(PROBE, "quokkarow")}` }, needle: "quokkarow",
    check: (m) => m.tag === "TR" && m.text.includes("r2a"), expected: "TR r2a",
  }),
  candidateScenario({
    name: "d callout",
    query: "quokkacallout", row: { sub: `locator-probe · L${lineOf(PROBE, "quokkacallout")}` }, needle: "quokkacallout",
    check: (m) => m.tag === "DIV" && m.text.includes("Callout title"), expected: "callout DIV",
  }),
  candidateScenario({
    name: "e formatted line",
    query: "quokkafmt", row: { sub: `locator-probe · L${lineOf(PROBE, "quokkafmt")}` }, needle: "quokkafmt",
    check: (m) => m.tag === "P" && m.text.startsWith("Link alias text"), expected: "P 'Link alias text and bold…'",
  }),
  candidateScenario({
    name: "a4 multi-line paragraph line",
    query: "quokkapara", row: { sub: `locator-probe · L${lineOf(PROBE, "quokkapara")}` }, needle: "quokkapara",
    check: (m) => m.tag === "P" && m.text.startsWith("First paragraph"), expected: "whole P containing the line",
  }),
  {
    name: "f same-file switch re-scrolls, no re-render",
    input: 'type "quokka"; select quokkanest; tag a child with an expando; select quokkafmt',
    expected: "scrollTop changes, flash moves, expando child still attached",
    run: async (ctx) => {
      const { client, json } = ctx;
      await openWithCandidates(ctx, "quokka");
      await select(ctx, { sub: `locator-probe · L${lineOf(PROBE, "quokkanest")}` });
      await waitFlash(ctx, "quokkanest");
      await settle();
      const first = await measure(ctx);
      await client.evaluate(`const c = document.querySelector(${json(PREVIEW)}); window.__dgKid = c.children[3]; window.__dgKid.__dgProbe = 42; return true;`);
      await select(ctx, { sub: `locator-probe · L${lineOf(PROBE, "quokkafmt")}` });
      await waitFlash(ctx, "quokkafmt");
      await settle();
      const second = await measure(ctx);
      const survived = await client.evaluate(`const c = document.querySelector(${json(PREVIEW)}); return c.contains(window.__dgKid) && window.__dgKid.__dgProbe === 42;`);
      return { first, second, survived };
    },
    expect: ({ first, second, survived }) => ({
      pass: survived && first.scrollTop !== second.scrollTop && second.inView && second.flashCount === 1 && second.text.startsWith("Link"),
      actual: `first ${fmt(first)} | second ${fmt(second)} | expando survived=${survived}`,
    }),
  },
  {
    name: "g non-candidate node resets to top",
    input: 'type "reset"; select candidate L-line in "Quokka reset node"; then the node row itself (same file)',
    expected: "candidate scrolls > 0; node result scrollTop 0 without re-render",
    run: async (ctx) => {
      const { client, json } = ctx;
      await openWithCandidates(ctx, "reset");
      await select(ctx, { sub: `Quokka reset node · L${lineOf(RESET, "Quokkareset")}` });
      await waitFlash(ctx, "Quokkareset");
      await settle();
      const cand = await measure(ctx);
      await client.evaluate(`const c = document.querySelector(${json(PREVIEW)}); window.__dgKid = c.children[3]; window.__dgKid.__dgProbe = 7; return true;`);
      await select(ctx, { title: "Quokka reset node" });
      await client.waitFor(`document.querySelector(${json(PREVIEW)}).scrollTop === 0`, { label: "scrollTop 0" });
      await settle();
      const node = await measure(ctx);
      const sameDom = await client.evaluate(`return document.querySelector(${json(PREVIEW)}).contains(window.__dgKid);`);
      return { cand, node, sameDom };
    },
    expect: ({ cand, node, sameDom }) => ({
      pass: cand.scrollTop > 0 && node.scrollTop === 0 && node.flashCount === 0,
      actual: `candidate ${fmt(cand)} | node scrollTop=${node.scrollTop} flash=${node.flashCount} sameDom=${sameDom}`,
    }),
  },
  {
    name: "h text fallback on block-count mismatch",
    input: 'type "quokka"; select quokkacallout; prepend a <p> to the preview; select quokkanest, quokkafmt, quokkarow',
    expected: "li/p found by unique text; tr (not a text-fallback tag) gets no flash",
    run: async (ctx) => {
      const { client, json } = ctx;
      await openWithCandidates(ctx, "quokka");
      await select(ctx, { sub: `locator-probe · L${lineOf(PROBE, "quokkacallout")}` });
      await waitFlash(ctx, "quokkacallout");
      await client.evaluate(`const c = document.querySelector(${json(PREVIEW)}); const p = document.createElement("p"); p.textContent = "injected extra block"; c.prepend(p); return true;`);
      const out = {};
      for (const needle of ["quokkanest", "quokkafmt"]) {
        await select(ctx, { sub: `locator-probe · L${lineOf(PROBE, needle)}` });
        await waitFlash(ctx, needle);
        await settle();
        out[needle] = await measure(ctx);
      }
      await select(ctx, { sub: `locator-probe · L${lineOf(PROBE, "quokkarow")}` });
      await new Promise((r) => setTimeout(r, 800));
      out.quokkarow = await measure(ctx);
      out.injectedStill = await client.evaluate(`return document.querySelector(${json(PREVIEW)}).firstElementChild.textContent === "injected extra block";`);
      return out;
    },
    expect: (o) => ({
      pass: o.injectedStill && o.quokkanest.tag === "LI" && o.quokkanest.text.startsWith("level2 B") && o.quokkanest.inView &&
        o.quokkafmt.tag === "P" && o.quokkafmt.text.startsWith("Link") && o.quokkafmt.inView && o.quokkarow.flashCount === 0,
      actual: `nest ${fmt(o.quokkanest)} | fmt ${fmt(o.quokkafmt)} | row flash=${o.quokkarow.flashCount} | injected kept=${o.injectedStill}`,
    }),
  },
  {
    name: "i flash cleared after ~3.5s",
    input: 'type "zephyrpara"; select; wait 3.5s',
    expected: "flash present at ~0.3s, gone by 3.5s (animationend)",
    run: async (ctx) => {
      await openWithCandidates(ctx, "zephyrpara");
      await select(ctx, { sub: `zephyr-candidates · L${lineOf(ZEPHYR, "Zephyrpara")}` });
      await waitFlash(ctx, "Zephyrpara");
      const t0 = Date.now();
      const early = await measure(ctx);
      await new Promise((r) => setTimeout(r, 3500));
      const late = await measure(ctx);
      return { early, late, waited: Date.now() - t0 };
    },
    expect: ({ early, late, waited }) => ({
      pass: early.flashCount === 1 && late.flashCount === 0 && late.scrollTop === early.scrollTop,
      actual: `early flash=${early.flashCount}; after ${waited}ms flash=${late.flashCount}; scrollTop ${early.scrollTop}->${late.scrollTop}`,
    }),
  },
];

